import React, { useState, useEffect, useRef } from 'react';
import flatpickr from 'flatpickr';

function AgeCalculator() {
  const [birthDate, setBirthDate] = useState('');
  const [age, setAge] = useState(null);
  const datePickerRef = useRef(null);
  const fpInstance = useRef(null);

  useEffect(() => {
    fpInstance.current = flatpickr(datePickerRef.current, {
      dateFormat: 'Y-m-d',
      maxDate: new Date(),
      placeholder: 'Select your birth date',
      onChange: (selectedDates) => {
        if (selectedDates.length > 0) {
          const date = selectedDates[0];
          setBirthDate(formatDate(date));
          calculateAge(date);
        }
      }
    });

    return () => {
      if (fpInstance.current) {
        fpInstance.current.destroy();
      }
    };
  }, []);

  const formatDate = (date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const calculateAge = (birthDate) => {
    const today = new Date();
    const birth = new Date(birthDate);

    let years = today.getFullYear() - birth.getFullYear();
    let months = today.getMonth() - birth.getMonth();
    let days = today.getDate() - birth.getDate();

    if (days < 0) {
      months--;
      const prevMonth = new Date(today.getFullYear(), today.getMonth(), 0);
      days += prevMonth.getDate();
    }

    if (months < 0) {
      years--;
      months += 12;
    }

    setAge({ years, months, days });
  };

  return (
    <div className="container">
      <h1>Age Calculator</h1>
      <div className="input-group">
        <label>Select your birth date:</label>
        <input
          ref={datePickerRef}
          type="text"
          className="date-input"
          placeholder="Select date"
          readOnly
        />
      </div>
      {age && (
        <div className="result">
          <h2>Your Age:</h2>
          <div className="age-display">
            <span className="age-item">{age.years}</span>
            <span className="age-label">years</span>
            <span className="age-item">{age.months}</span>
            <span className="age-label">months</span>
            <span className="age-item">{age.days}</span>
            <span className="age-label">days</span>
          </div>
        </div>
      )}
    </div>
  );
}

export default AgeCalculator;
